--- a/average.c
+++ b/average.c
@@ -1,4 +1,7 @@
 /* Mean of `count` sensor samples whose total is `sum`. */
 int average(int sum, int count) {
+  if (count <= 0) {
+    return 0;
+  }
   return sum / count;
 }

--- a/buffer.c
+++ b/buffer.c
@@ -3,6 +3,6 @@

 /* Zero every slot of the frame before reuse. */
 void clear_frame(void) {
-  for (int i = 0; i <= 8; i++)
+  for (int i = 0; i < 8; i++)
     frame[i] = 0;
 }

--- a/pitch.c
+++ b/pitch.c
@@ -1,7 +1,15 @@
 /* Pitch-rate command from attitude error and controller gain. */
 int pitch_cmd(int error, int gain) {
-  int out = error * gain;
+  long long product = (long long)error * (long long)gain;
+  int out;
+  if (product > 1000) {
+    out = 1000;
+  } else if (product < -1000) {
+    out = -1000;
+  } else {
+    out = (int)product;
+  }
   __CPROVER_assert(out >= -1000 && out <= 1000,
                    "REQ-PITCH-1: pitch command within +/-1000");
   return out;
-}
+}
\ No newline at end of file

--- a/ring.c
+++ b/ring.c
@@ -3,6 +3,10 @@

 /* Store `value` at slot `head`; return the next slot. */
 int ring_put(int head, int value) {
-  ring[head] = value;
-  return (head + 1) % 4;
+  int idx = head % 4;
+  if (idx < 0) {
+    idx += 4;
+  }
+  ring[idx] = value;
+  return (idx + 1) % 4;
 }

