 int pitch_cmd(int error, int gain) {
-  int out = error * gain;
+  long long out_ll = (long long)error * gain;
+  if (out_ll > 1000) {
+    out_ll = 1000;
+  } else if (out_ll < -1000) {
+    out_ll = -1000;
+  }
+  int out = (int)out_ll;
   __CPROVER_assert(out >= -1000 && out <= 1000,
