 int ring_put(int head, int value) {
-  ring[head] = value;
-  return (head + 1) % 4;
+  unsigned int idx = (unsigned int)head & 3;
+  ring[idx] = value;
+  return (idx + 1) % 4;
 }

--- a/scale.c
+++ b/scale.c
@@ -1,4 +1,21 @@
 /* Scale a raw ADC count by a power of two. */
 int scale(int raw, int shift) {
-  return raw << shift;
+  if (shift < 0) {
+    shift = 0;
+  } else if (shift > 15) {
+    shift = 15;
+  }
+
+  long long res = (long long)raw * (1LL << shift);
+
+  int max_val = (int)(((1ULL << (sizeof(int) * 8 - 1)) - 1));
+  int min_val = -max_val - 1;
+
+  if (res > max_val) {
+    return max_val;
+  } else if (res < min_val) {
+    return min_val;
+  } else {
+    return (int)res;
+  }
 }
